-- Seed gerado por assets/gerador-avaliacao-discursiva (não editar à mão; fora do Git).
-- Rodar depois de database/2026-10-01-respostas-discursivas.sql. Idempotente.
-- A avaliação nasce BLOQUEADA (ativo = false): o professor libera no índice de atividades.
do $$
declare
  v_aula bigint;
  v_atividade bigint;
begin
  select a.id into v_aula from public.aulas a join public.materia m on m.id = a.materia_id
    where m.descricao = 'BANCO DE DADOS' and a.numero = 20
    order by a.id limit 1;
  if v_aula is null then
    raise exception 'Aula 20 da matéria não encontrada';
  end if;

  insert into public.atividade (nome_atividade, status, aula_id, descricao, pagina,
      total_itens, ativo)
    values ('Avaliação Prática', 'PENDENTE', v_aula, 'Atividade — Avaliação Prática (20 questões discursivas)',
      '/MATERIAIS/TECNICO-INFORMATICA-INTERNET/BANCO-DE-DADOS/ATIVIDADES/AVALIACAO-PRATICA.html', 20, false)
    on conflict (pagina) do update set aula_id = excluded.aula_id,
      descricao = excluded.descricao, total_itens = excluded.total_itens
    returning id into v_atividade;

  delete from public.topico_discursivo where atividade_id = v_atividade;
  insert into public.topico_discursivo (atividade_id, item, topico, enunciado, pontos,
      resposta_esperada, criterios) values
      (v_atividade, 1, 1, 'Explique a diferença entre requisito de dados e regra de negócio, com um exemplo de cada tirado de R1 a R8.', 0.1, '**Requisito de dados** diz **o que precisa ser guardado** (ex.: R1 — nome, CPF, e-mail e telefones do leitor). **Regra de negócio** diz **uma condição que os dados precisam obedecer** e vira restrição, procedimento ou trigger (ex.: R5 — no máximo 3 empréstimos em aberto; ou R4 — um exemplar só num empréstimo aberto).', 'Nota cheia (0,1): as duas definições com um exemplo correto de cada. Metade (0,05): só as definições, ou exemplos sem a diferença. Zero (0): definições trocadas ou sem relação.'),
      (v_atividade, 1, 2, 'Diga como cada um dos requisitos R4, R5, R7 e R8 será atendido no banco (tabela ou coluna, restrição, procedimento, trigger ou permissão).', 0.2, '**R4** = tabela **emprestimo** (datas) + índice único parcial em id_exemplar onde data_devolucao é nula (ou regra no procedimento). **R5** = **procedimento emprestar**, que confere leitor ativo, atraso e o limite de 3. **R7** = tabela **historico_exemplar** + **trigger** no UPDATE da situação do exemplar. **R8** = **papéis e GRANT/REVOKE** (grupo do balcão sem SELECT no CPF, coordenação só na visão, app_biblioteca só o necessário).', 'Nota cheia (0,2): os quatro requisitos ligados ao objeto certo. Metade (0,1): dois ou três certos. Zero (0): um ou nenhum.'),
      (v_atividade, 1, 3, 'Explique como a equipe deve tratar o pedido de reserva e SMS e o que precisa ser registrado no documento de escopo.', 0.2, 'É **mudança de escopo**: reserva e SMS **não estão** em R1 a R8. A equipe registra o pedido, **avalia o impacto** (novas tabelas como reserva, integração de SMS, prazo e custo) e só inclui com **nova aprovação** do cliente, ajustando o prazo; ou deixa para uma **próxima versão**. No documento de escopo: o pedido, a data, quem pediu, a decisão (entra/não entra), o impacto e o item no "não entra" se ficar de fora.', 'Nota cheia (0,2): reconhece a mudança de escopo + avaliação de impacto/aprovação + o que registrar. Metade (0,1): só aceita ou recusa com motivo, sem dizer o que registrar (ou registra sem avaliar o impacto). Zero (0): inclui direto sem análise, ou sem relação.'),
      (v_atividade, 2, 1, 'Explique por que um SGBD relacional como o PostgreSQL atende melhor a este caso do que a planilha compartilhada.', 0.1, 'O SGBD relacional garante **integridade** (chaves, UNIQUE, CHECK impedem CPF repetido e exemplar emprestado duas vezes), **acesso simultâneo** de vários atendentes com **transações** e bloqueio, **controle de acesso** por usuário (o balcão sem CPF) e **backup**. A planilha aceita dados duplicados ou errados, um sobrescreve o outro e qualquer um vê tudo.', 'Nota cheia (0,1): pelo menos duas vantagens ligadas ao caso. Metade (0,05): uma vantagem, ou vantagens genéricas sem o caso. Zero (0): sem relação.'),
      (v_atividade, 2, 2, 'Escreva os comandos que criam o banco biblioteca_db, o usuário app_biblioteca da aplicação com permissão de conexão, a linha do pg_hba.conf que libera só o servidor de aplicação com senha e o comando que recarrega a configuração.', 0.2, '```sql', 'Nota cheia (0,2): banco + usuário com LOGIN e senha + CONNECT + linha do pg_hba com o IP 10.0.0.20 e scram-sha-256 (ou md5) + recarga. Metade (0,1): falta a linha do pg_hba ou o banco/usuário, ou usa `trust`/`0.0.0.0/0`. Zero (0): usa o superusuário postgres na aplicação ou comandos sem relação.'),
      (v_atividade, 2, 3, 'Explique os três níveis de gerenciamento de dados (externo, conceitual e físico) com um exemplo de cada no banco da biblioteca.', 0.2, '**Externo** = o que cada usuário ou tela vê (ex.: tela do balcão ou visão sem o CPF; relatório da coordenação). **Conceitual/lógico** = todas as tabelas, colunas, chaves e regras (ex.: leitor, livro, exemplar, emprestimo). **Físico/interno** = como o SGBD grava no disco: arquivos de dados, páginas e índices (ex.: o índice único dos empréstimos em aberto). A separação dá **independência**: muda-se um nível sem quebrar o outro.', 'Nota cheia (0,2): os três níveis com exemplo correto do caso. Metade (0,1): dois níveis certos, ou os três sem exemplo do caso. Zero (0): níveis trocados ou sem relação.'),
      (v_atividade, 3, 1, 'Explique o que são entidade forte, entidade fraca e entidade associativa.', 0.1, '**Forte** existe sozinha, com identificador próprio (ex.: leitor). **Fraca** só existe ligada a outra e depende dela para ser identificada (ex.: telefone do leitor). **Associativa** nasce de um relacionamento N:N e liga duas entidades, podendo ter atributos próprios (ex.: empréstimo).', 'Nota cheia (0,1): as três definições corretas. Metade (0,05): duas certas. Zero (0): uma ou nenhuma.'),
      (v_atividade, 3, 2, 'Liste as entidades do caso e classifique cada uma em forte, fraca ou associativa.', 0.2, '**Fortes:** LEITOR, LIVRO, AUTOR, EDITORA, CATEGORIA. **Fracas:** TELEFONE_LEITOR (depende do leitor), EXEMPLAR (só existe para um livro; aceitar como forte se justificar o tombo como identificador próprio), HISTORICO_EXEMPLAR (depende do exemplar). **Associativas:** LIVRO_AUTOR (livro N:N autor) e EMPRESTIMO (leitor N:N exemplar, com datas e multa).', 'Nota cheia (0,2): todas as entidades principais (leitor, livro, autor, editora, categoria, exemplar, empréstimo) presentes e classificadas corretamente, com as duas associativas. Metade (0,1): falta uma ou duas entidades ou uma classificação errada (ex.: empréstimo como forte). Zero (0): lista com atributos no lugar de entidades ou quase tudo errado.'),
      (v_atividade, 3, 3, 'Explique por que EXEMPLAR precisa ser uma entidade separada de LIVRO e por que a proposta do colega não atende a R3, R4 e R7.', 0.2, 'O **livro** é a obra (título, ISBN, autores); o **exemplar** é cada cópia física, com **tombo próprio** e **situação própria** (R3): duas cópias do mesmo livro podem estar uma emprestada e outra disponível. A proposta do colega guarda **só um leitor e uma data por livro** (não registra vários empréstimos nem o histórico — R4), não identifica qual cópia saiu (R3) e não guarda as mudanças de situação (R7); "quantidade_disponivel" é dado **derivado** que fica inconsistente.', 'Nota cheia (0,2): diferença obra × cópia física + pelo menos dois problemas da proposta ligados a R3, R4 ou R7. Metade (0,1): só a diferença, ou só os problemas. Zero (0): concorda com a proposta ou sem relação.'),
      (v_atividade, 4, 1, 'Explique o que são atributo simples, composto, multivalorado, derivado e identificador.', 0.1, '**Simples** = não se divide (e-mail). **Composto** = formado por partes (endereço: rua, número, cidade). **Multivalorado** = pode ter vários valores (telefones). **Derivado** = calculado de outros (dias de atraso). **Identificador** = identifica cada ocorrência (id_leitor; CPF como chave candidata).', 'Nota cheia (0,1): os cinco tipos certos. Metade (0,05): três ou quatro certos. Zero (0): dois ou menos.'),
      (v_atividade, 4, 2, 'Liste os atributos de LEITOR e classifique cada um, dizendo qual é o identificador e qual é a chave candidata.', 0.2, 'id_leitor — **identificador** (chave primária); nome — simples (aceitar composto: nome e sobrenome); cpf — simples, **chave candidata** (único); email — simples, único (também candidata); data_cadastro — simples; ativo — simples (sim/não); telefones — **multivalorado**.', 'Nota cheia (0,2): atributos de R1 listados, identificador e chave candidata (CPF ou e-mail) corretos e telefones como multivalorado. Metade (0,1): lista certa com uma classificação errada ou sem a chave candidata. Zero (0): sem identificador ou classificações quase todas erradas.'),
      (v_atividade, 4, 3, 'Diga como o atributo multivalorado telefones vira estrutura no banco e explique por que "dias de atraso" não é gravado, mas o valor da multa é.', 0.2, 'Telefones viram a tabela **telefone_leitor** (id_telefone, **id_leitor** FK, numero), uma linha por telefone — nunca colunas tel1, tel2. **Dias de atraso** é **derivado** e muda todo dia (CURRENT_DATE − data_prevista): é **calculado na consulta**, gravar deixaria o dado desatualizado. A **multa** é gravada porque é o **valor cobrado no momento da devolução** (R6), um fato que precisa ficar fixo no histórico mesmo que a regra mude depois.', 'Nota cheia (0,2): tabela de telefones com FK + motivo de não gravar os dias + motivo de gravar a multa. Metade (0,1): duas das três partes. Zero (0): colunas tel1/tel2 e sem justificativa, ou sem relação.'),
      (v_atividade, 5, 1, 'Explique o que significam as cardinalidades 1:1, 1:N e N:N.', 0.1, '**1:1** = cada ocorrência de um lado liga a no máximo uma do outro. **1:N** = uma ocorrência de um lado liga a várias do outro, e cada uma destas liga a só uma. **N:N** = várias de um lado ligam a várias do outro.', 'Nota cheia (0,1): as três corretas. Metade (0,05): duas corretas. Zero (0): uma ou nenhuma.'),
      (v_atividade, 5, 2, 'Escreva a cardinalidade de: editora–livro, categoria–livro, livro–autor, livro–exemplar, leitor–telefone e leitor–empréstimo.', 0.2, 'editora–livro **1:N**; categoria–livro **1:N**; livro–autor **N:N**; livro–exemplar **1:N**; leitor–telefone **1:N**; leitor–empréstimo **1:N**.', 'Nota cheia (0,2): as seis certas. Metade (0,1): quatro ou cinco certas. Zero (0): três ou menos.'),
      (v_atividade, 5, 3, 'Explique como os relacionamentos N:N livro–autor e leitor–exemplar são resolvidos em tabelas, dizendo as chaves de cada tabela criada.', 0.2, '**livro–autor** vira a tabela associativa **livro_autor** (id_livro FK, id_autor FK) com **chave primária composta (id_livro, id_autor)**. **leitor–exemplar** (um leitor leva vários exemplares e um exemplar é levado por vários leitores ao longo do tempo) vira a tabela **emprestimo**, com **chave primária própria id_emprestimo** e as FKs **id_leitor** e **id_exemplar**, mais os atributos do relacionamento (datas e multa). A PK própria é necessária porque o mesmo leitor pode pegar o mesmo exemplar mais de uma vez.', 'Nota cheia (0,2): as duas tabelas com PK e FKs corretas. Metade (0,1): só uma das duas certa, ou as duas sem dizer as chaves. Zero (0): resolve N:N com FK numa das pontas ou sem relação.'),
      (v_atividade, 6, 1, 'Explique o que representam no DER: o retângulo, o losango (ou a linha de ligação), o atributo sublinhado e a marcação de cardinalidade.', 0.1, '**Retângulo** = entidade (tabela); **losango** (ou a linha de ligação no modelo lógico) = relacionamento; atributo **sublinhado** = identificador (chave primária); **marcação de cardinalidade** (1, N; pé de galinha; (0,1)/(1,N)) = quantos de um lado se ligam ao outro.', 'Nota cheia (0,1): os quatro elementos certos. Metade (0,05): dois ou três certos. Zero (0): um ou nenhum.'),
      (v_atividade, 6, 2, 'Descreva em texto o DER lógico do caso: cada tabela com a chave primária, as chaves estrangeiras e as ligações com cardinalidade.', 0.2, 'editora (**id_editora** PK, nome, cidade); categoria (**id_categoria** PK, nome); autor (**id_autor** PK, nome); livro (**id_livro** PK, titulo, isbn, ano_publicacao, id_editora FK, id_categoria FK); livro_autor (**id_livro + id_autor** PK, ambos FK); exemplar (**id_exemplar** PK, id_livro FK, codigo_tombo, situacao); leitor (**id_leitor** PK, nome, cpf, email, data_cadastro, ativo); telefone_leitor (**id_telefone** PK, id_leitor FK, numero); emprestimo (**id_emprestimo** PK, id_exemplar FK, id_leitor FK, datas, valor_multa); historico_exemplar (**id_historico** PK, id_exemplar FK, situações, usuario, alterado_em). Ligações: editora 1:N livro; categoria 1:N livro; livro 1:N livro_autor N:1 autor; livro 1:N exemplar; leitor 1:N telefone_leitor; leitor 1:N emprestimo; exemplar 1:N emprestimo; exemplar 1:N historico_exemplar.', 'Nota cheia (0,2): todas as tabelas principais com PK e FK certas e ligações com cardinalidade (aceitar sem historico_exemplar). Metade (0,1): falta uma tabela, as FKs ou as cardinalidades. Zero (0): sem chaves ou sem relação com o caso.'),
      (v_atividade, 6, 3, 'Escreva o dicionário de dados da tabela emprestimo (coluna, tipo, obrigatório e restrição ou descrição).', 0.2, '| Coluna | Tipo | Obrigatório | Restrição / descrição |', 'Nota cheia (0,2): todas as colunas com tipo, obrigatoriedade e restrição/descrição coerentes, com PK, FKs e data_devolucao opcional. Metade (0,1): falta uma ou duas colunas ou as restrições. Zero (0): sem chaves ou tabela errada.'),
      (v_atividade, 7, 1, 'Explique a regra de cada forma normal: 1FN, 2FN e 3FN.', 0.1, '**1FN** = cada célula com um único valor (atômico), sem grupos repetidos. **2FN** = está na 1FN e todo atributo não chave depende da **chave inteira** (sem dependência parcial de parte da chave composta). **3FN** = está na 2FN e nenhum atributo não chave depende de **outro atributo não chave** (sem dependência transitiva).', 'Nota cheia (0,1): as três regras corretas. Metade (0,05): duas corretas. Zero (0): uma ou nenhuma.'),
      (v_atividade, 7, 2, 'Aponte o que viola a 1FN na planilha e a dependência parcial (2FN) que aparece quando cada autor vira uma linha com chave (num_emprestimo, autor).', 0.2, 'Violam a **1FN**: **telefones_leitor** e **autores** (vários valores na mesma célula). Separando cada autor numa linha, a chave passa a ser (num_emprestimo, autor) e **titulo, cpf_leitor, datas, tombo** etc. dependem **só de num_emprestimo** (parte da chave): é a **dependência parcial** que viola a 2FN. Solução: autor vai para outra tabela ligada ao livro.', 'Nota cheia (0,2): os dois multivalorados + a dependência parcial explicada. Metade (0,1): só a 1FN ou só a 2FN. Zero (0): sem relação.'),
      (v_atividade, 7, 3, 'Aponte as dependências transitivas (3FN) e escreva as tabelas finais normalizadas, com as chaves.', 0.2, 'Transitivas: num_emprestimo → cpf_leitor → **nome_leitor**; num_emprestimo → tombo → isbn → **titulo, editora**; editora → **cidade_editora**. Tabelas finais: leitor (**id_leitor**, cpf, nome), telefone_leitor (**id_telefone**, id_leitor, numero), editora (**id_editora**, nome, cidade), livro (**id_livro**, isbn, titulo, id_editora), autor (**id_autor**, nome), livro_autor (**id_livro, id_autor**), exemplar (**id_exemplar**, codigo_tombo, id_livro), emprestimo (**id_emprestimo**, id_leitor, id_exemplar, data_emprestimo, data_prevista).', 'Nota cheia (0,2): pelo menos duas transitivas certas + tabelas finais com chaves sem repetição. Metade (0,1): só as dependências ou tabelas com uma repetição restante (ex.: cidade_editora no livro). Zero (0): tabelas que repetem dados ou sem relação.'),
      (v_atividade, 8, 1, 'Explique por que padronizar nomes, tipos e domínios antes de escrever o DDL.', 0.1, 'Sem padrão cada pessoa escreve de um jeito ("DataEmp", "dt prev") e os valores chegam diferentes ("DISP", "Disponível"), e as **consultas e filtros erram**. Padronizar antes do DDL deixa o banco **previsível, legível** e fácil de integrar com o back-end, e evita renomear tabelas depois.', 'Nota cheia (0,1): problema da falta de padrão + benefício. Metade (0,05): só um dos dois. Zero (0): sem relação.'),
      (v_atividade, 8, 2, 'Reescreva os nomes do rascunho no padrão adotado na UC e diga como garantir no banco os valores da situação do exemplar.', 0.2, 'Leitores → **leitor**; DataEmp → **data_emprestimo**; dt prev → **data_prevista**; Situação → **situacao**; tel1/tel2 → tabela **telefone_leitor** com a coluna **numero**; valorMulta → **valor_multa**; user → **usuario** (user é palavra reservada). Situação com **lista fechada**: `CHECK (situacao IN (''disponivel'', ''emprestado'', ''baixado''))` (aceitar tabela de apoio com FK) e valores sempre em minúsculas, sem acento.', 'Nota cheia (0,2): nomes em minúsculas, singular, sem acento, com `_` (tel1/tel2 resolvidos em tabela) + domínio fechado por CHECK ou tabela de apoio. Metade (0,1): só os nomes ou só o domínio. Zero (0): mantém acentos/espaços/maiúsculas ou sem relação.'),
      (v_atividade, 8, 3, 'Descreva o fluxograma do empréstimo no balcão (início, decisões de R5, ações e fim), dizendo em cada passo a tabela consultada ou alterada.', 0.2, '**Início** → atendente informa o leitor e o tombo → consulta **leitor**: está ativo? (não → recusa, fim) → consulta **emprestimo**: tem empréstimo atrasado? (sim → recusa, fim) → tem 3 em aberto? (sim → recusa, fim) → consulta **exemplar**: está disponível? (não → recusa, fim) → grava em **emprestimo** (data prevista = hoje + 14) → muda **exemplar** para emprestado (o trigger grava **historico_exemplar**) → entrega o comprovante → **Fim**.', 'Nota cheia (0,2): início e fim, as decisões de R5 (ativo, atraso, limite de 3) e a disponibilidade, com as tabelas de cada passo. Metade (0,1): fluxo sem as tabelas ou faltando duas decisões. Zero (0): sem decisões ou sem relação.'),
      (v_atividade, 9, 1, 'Explique a escolha dos tipos serial, varchar, char, date, boolean e numeric no caso da biblioteca.', 0.1, '**serial** = número automático para a chave primária; **varchar(n)** = texto de tamanho variável (nome, título, e-mail); **char(n)** = texto de tamanho fixo (CPF com 11, ISBN com 13); **date** = datas do empréstimo, comparáveis e com cálculo de dias; **boolean** = sim/não (ativo); **numeric(8,2)** = dinheiro com 2 casas exatas (multa), sem erro de arredondamento.', 'Nota cheia (0,1): pelo menos cinco tipos com uso certo no caso. Metade (0,05): três ou quatro certos. Zero (0): dois ou menos, ou usa texto para datas e dinheiro.'),
      (v_atividade, 9, 2, 'Escreva o CREATE TABLE de editora, categoria e autor, com chave primária e colunas obrigatórias.', 0.2, '```sql', 'Nota cheia (0,2): as três tabelas com PK, tipos coerentes e NOT NULL nos nomes (cidade na editora). Metade (0,1): falta uma tabela, a PK ou os NOT NULL. Zero (0): sintaxe que não roda no PostgreSQL ou sem relação.'),
      (v_atividade, 9, 3, 'Escreva o CREATE TABLE de leitor e de telefone_leitor (R1) e justifique por que o CPF é texto de 11 caracteres e não número.', 0.2, '```sql', 'Nota cheia (0,2): as duas tabelas com PK, UNIQUE em cpf e email, FK do telefone para o leitor + justificativa do CPF (zero à esquerda ou não é usado em cálculo). Metade (0,1): tabelas certas sem a justificativa, ou justificativa com tabela sem FK/UNIQUE. Zero (0): CPF numérico sem justificativa e sem FK, ou sem relação.'),
      (v_atividade, 10, 1, 'Explique a função de PRIMARY KEY, FOREIGN KEY, UNIQUE, NOT NULL e CHECK.', 0.1, '**PRIMARY KEY** identifica cada linha (única e não nula); **FOREIGN KEY** liga a uma linha que existe em outra tabela (integridade referencial); **UNIQUE** impede valor repetido (ISBN, tombo, CPF); **NOT NULL** obriga o preenchimento; **CHECK** aceita só valores que cumprem uma condição (situação da lista, multa ≥ 0).', 'Nota cheia (0,1): as cinco restrições certas. Metade (0,05): três ou quatro certas. Zero (0): duas ou menos.'),
      (v_atividade, 10, 2, 'Escreva o CREATE TABLE de livro, livro_autor e exemplar com chaves primárias, chaves estrangeiras, UNIQUE do ISBN e do tombo e CHECK da situação.', 0.2, '```sql', 'Nota cheia (0,2): as três tabelas com PK (composta na livro_autor), FKs, UNIQUE do ISBN e do tombo e CHECK da situação. Metade (0,1): falta a PK composta, uma FK ou o CHECK/UNIQUE. Zero (0): sem FKs ou sintaxe que não roda.'),
      (v_atividade, 10, 3, 'Escreva o CREATE TABLE de emprestimo com as restrições de datas e de multa e o índice que impede dois empréstimos em aberto do mesmo exemplar (R4), e explique o efeito de ON DELETE RESTRICT nas chaves estrangeiras.', 0.2, '```sql', 'Nota cheia (0,2): tabela com FKs, CHECK das datas e da multa + índice único parcial (ou outra garantia equivalente no banco) + explicação do RESTRICT. Metade (0,1): falta o índice parcial ou a explicação, ou faltam os CHECK. Zero (0): sem FKs ou usa CASCADE dizendo que preserva o histórico.'),
      (v_atividade, 11, 1, 'Explique a diferença entre INSERT, UPDATE e o comando de exclusão e por que, neste caso, o leitor que se mudou é inativado em vez de excluído.', 0.1, '**INSERT** acrescenta linhas, **UPDATE** altera valores de linhas existentes e o **comando de exclusão** remove linhas; UPDATE e exclusão precisam de **WHERE**, senão atingem a tabela inteira. O leitor com empréstimos **não é excluído** porque a FK (RESTRICT) impede e porque o **histórico** de empréstimos e multas precisa continuar: ele é **inativado** (ativo = false).', 'Nota cheia (0,1): os três comandos + motivo de inativar (FK/histórico). Metade (0,05): só os comandos, ou só o motivo. Zero (0): sem relação.'),
      (v_atividade, 11, 2, 'Escreva os INSERT de uma editora, uma categoria, um autor, um livro com o seu autor, dois exemplares e um leitor com telefone.', 0.2, '```sql', 'Nota cheia (0,2): todos os INSERT na ordem das dependências (pai antes do filho), com as colunas citadas e a ligação livro_autor. Metade (0,1): falta um ou dois INSERT ou ordem que quebra uma FK. Zero (0): INSERT sem relação com as tabelas do caso ou dados pessoais reais.'),
      (v_atividade, 11, 3, 'Escreva, numa transação, a devolução do empréstimo 1 com a multa de R6 e o exemplar de volta a disponível, e o UPDATE que inativa o leitor.', 0.2, '```sql', 'Nota cheia (0,2): BEGIN/COMMIT com as duas atualizações (devolução com multa e exemplar disponível) com WHERE + UPDATE que inativa o leitor. Metade (0,1): sem transação, ou falta uma das atualizações, ou falta a inativação. Zero (0): UPDATE sem WHERE ou exclusão do leitor.'),
      (v_atividade, 12, 1, 'Explique a função de WHERE, ORDER BY, BETWEEN, ILIKE e IS NULL.', 0.1, '**WHERE** filtra as linhas; **ORDER BY** ordena o resultado (ASC/DESC); **BETWEEN** filtra uma faixa com os limites incluídos; **ILIKE** compara texto com padrão (% = qualquer sequência) sem diferenciar maiúsculas; **IS NULL** testa se o valor está vazio (nulo).', 'Nota cheia (0,1): os cinco certos. Metade (0,05): três ou quatro certos. Zero (0): dois ou menos.'),
      (v_atividade, 12, 2, 'Escreva a consulta 1 (livros publicados entre 2000 e 2020, do mais novo para o mais antigo e, no mesmo ano, por título) e a consulta 2 (leitores ativos cujo nome começa com "mar", sem diferença de maiúsculas, em ordem alfabética, só nome e e-mail).', 0.2, '```sql', 'Nota cheia (0,2): as duas consultas com filtro e ordenação certos (DESC no ano e desempate por título; ILIKE ou lower(...) LIKE e só nome e e-mail). Metade (0,1): uma consulta certa, ou as duas sem a ordenação pedida. Zero (0): nenhuma roda ou filtros errados.'),
      (v_atividade, 12, 3, 'Escreva a consulta 3: empréstimos em aberto e atrasados, com os dias de atraso calculados, do mais atrasado para o menos atrasado, e explique por que se usa IS NULL e não "= NULL".', 0.2, '```sql', 'Nota cheia (0,2): filtro de em aberto + atrasado, dias calculados, ordem decrescente + explicação do IS NULL. Metade (0,1): consulta certa sem a explicação, ou explicação com a consulta sem o cálculo/ordem. Zero (0): usa `= NULL` ou sem relação.'),
      (v_atividade, 13, 1, 'Explique a diferença entre INNER JOIN e LEFT JOIN.', 0.1, '**INNER JOIN** traz só as linhas que têm par nas duas tabelas. **LEFT JOIN** traz **todas** as linhas da tabela da esquerda, mesmo sem par, com as colunas da direita nulas.', 'Nota cheia (0,1): as duas definições certas. Metade (0,05): só uma certa. Zero (0): trocadas ou sem relação.'),
      (v_atividade, 13, 2, 'Escreva a consulta 4: empréstimos em aberto com o nome do leitor, o título do livro, o código de tombo e a data prevista, ordenados pela data prevista.', 0.2, '```sql', 'Nota cheia (0,2): as quatro tabelas ligadas pelas chaves certas (livro pelo exemplar), filtro de em aberto e ordenação. Metade (0,1): falta uma junção ou o filtro/ordem. Zero (0): junção sem condição (produto cartesiano) ou sem relação.'),
      (v_atividade, 13, 3, 'Escreva a consulta 5: livros sem nenhum exemplar, e explique por que ela precisa de LEFT JOIN e não de INNER JOIN.', 0.2, '```sql', 'Nota cheia (0,2): consulta certa com LEFT JOIN + IS NULL + explicação. Metade (0,1): consulta certa sem explicação, ou explicação certa com consulta incompleta. Zero (0): INNER JOIN ou sem relação.'),
      (v_atividade, 14, 1, 'Explique a função de GROUP BY e a diferença entre WHERE e HAVING.', 0.1, '**GROUP BY** junta as linhas com o mesmo valor para aplicar funções de agregação (count, sum, avg) por grupo. **WHERE** filtra as **linhas antes** de agrupar; **HAVING** filtra os **grupos depois** de agrupar, e pode usar as agregações.', 'Nota cheia (0,1): GROUP BY + diferença WHERE × HAVING. Metade (0,05): só uma das partes. Zero (0): sem relação.'),
      (v_atividade, 14, 2, 'Escreva a consulta 6: total de empréstimos por categoria, da categoria mais emprestada para a menos emprestada.', 0.2, '```sql', 'Nota cheia (0,2): junções até o empréstimo, count, GROUP BY da categoria e ordem decrescente. Metade (0,1): falta uma junção ou a ordem. Zero (0): sem GROUP BY ou sem relação.'),
      (v_atividade, 14, 3, 'Escreva a consulta 7: leitores com mais de 2 empréstimos em 2026, com a quantidade e a soma das multas, e explique por que o filtro do ano fica no WHERE e o "mais de 2" no HAVING.', 0.2, '```sql', 'Nota cheia (0,2): consulta com WHERE do ano, GROUP BY, HAVING count > 2 e soma das multas + explicação. Metade (0,1): consulta certa sem explicação, ou com o ano no HAVING. Zero (0): count no WHERE ou sem relação.'),
      (v_atividade, 15, 1, 'Explique o que é uma subconsulta e a diferença de uso entre IN e EXISTS.', 0.1, '**Subconsulta** é um SELECT dentro de outro comando, cujo resultado é usado pela consulta de fora. **IN** compara um valor com a **lista** devolvida pela subconsulta; **EXISTS** só verifica se a subconsulta **devolve alguma linha** (normalmente ligada à linha de fora — correlacionada) e é seguro com nulos (NOT IN com nulo não traz nada).', 'Nota cheia (0,1): definição + diferença IN × EXISTS. Metade (0,05): só uma das partes. Zero (0): sem relação.'),
      (v_atividade, 15, 2, 'Escreva a consulta 8 (livros que nunca foram emprestados, com NOT EXISTS) e a consulta 9 (empréstimos cuja multa é maior que a média das multas cobradas, só multas acima de zero).', 0.2, '```sql', 'Nota cheia (0,2): consulta 8 com NOT EXISTS correlacionado pelo livro passando pelo exemplar + consulta 9 com a média só das multas > 0. Metade (0,1): uma das duas certa, ou a 9 com a média de todos os empréstimos. Zero (0): nenhuma certa.'),
      (v_atividade, 15, 3, 'Escreva a consulta 10: o título ou os títulos mais emprestados, com a quantidade, usando subconsulta, e explique por que ela é mais segura que ORDER BY ... LIMIT 1.', 0.2, '```sql', 'Nota cheia (0,2): agrupamento por livro + HAVING comparando com o máximo da subconsulta + explicação do empate. Metade (0,1): consulta certa sem a explicação, ou só ORDER BY/LIMIT com a explicação do empate. Zero (0): sem relação.'),
      (v_atividade, 16, 1, 'Explique a diferença entre função e procedimento no PostgreSQL e por que o empréstimo é um procedimento.', 0.1, '**Função** (CREATE FUNCTION) **devolve um valor** e é chamada dentro de um SELECT. **Procedimento** (CREATE PROCEDURE) executa uma **ação** (gravar, alterar), é chamado com **CALL** e pode controlar transação. O empréstimo é procedimento porque **grava** o empréstimo e **muda** o exemplar, aplicando as regras de R5 num só lugar.', 'Nota cheia (0,1): diferença (retorno × ação; SELECT × CALL) + motivo no caso. Metade (0,05): só a diferença ou só o motivo. Zero (0): sem relação.'),
      (v_atividade, 16, 2, 'Escreva o procedimento emprestar(p_id_leitor, p_id_exemplar) em PL/pgSQL que confere o exemplar disponível e as regras de R5, grava o empréstimo com a data prevista de 14 dias e muda o exemplar para emprestado.', 0.2, '```sql', 'Nota cheia (0,2): confere exemplar disponível, leitor ativo, atraso e limite de 3 com RAISE EXCEPTION + INSERT com data prevista de 14 dias + UPDATE do exemplar. Metade (0,1): falta uma das regras de R5 ou o UPDATE do exemplar. Zero (0): sem as regras, sintaxe que não é PL/pgSQL ou função que não grava.'),
      (v_atividade, 16, 3, 'Escreva duas chamadas de teste com o resultado esperado (uma que funciona e uma barrada pelo limite de 3) e explique o papel do FOR UPDATE quando dois atendentes emprestam o mesmo exemplar.', 0.2, '`CALL emprestar(1, 1);` → **CALL**: exemplar 1 passa a ''emprestado'' e aparece em emprestimo com data_prevista = hoje + 14 (conferir com `SELECT situacao FROM exemplar WHERE id_exemplar = 1;`). Com o leitor 2 já com 3 empréstimos em aberto: `CALL emprestar(2, 5);` → **ERROR: Leitor 2 já tem 3 empréstimos em aberto** e nada é gravado. O **FOR UPDATE** **trava a linha** do exemplar (e do leitor) até o fim da transação: o segundo atendente **espera** e, quando continua, já lê ''emprestado'' e recebe o erro — o mesmo exemplar não sai em dois empréstimos.', 'Nota cheia (0,2): uma chamada que funciona e uma barrada, com o resultado esperado + o FOR UPDATE como trava da linha contra a corrida. Metade (0,1): só os testes ou só a explicação do FOR UPDATE. Zero (0): sem relação.'),
      (v_atividade, 17, 1, 'Explique o que é um trigger e o que são AFTER, FOR EACH ROW, OLD e NEW.', 0.1, '**Trigger** é uma rotina disparada **automaticamente** por um evento (INSERT, UPDATE ou exclusão) numa tabela, sem ninguém chamar. **AFTER** = roda depois de a alteração ser feita; **FOR EACH ROW** = roda uma vez para cada linha alterada; **OLD** = a linha como era antes; **NEW** = a linha como ficou.', 'Nota cheia (0,1): definição + AFTER, FOR EACH ROW, OLD e NEW. Metade (0,05): definição com só parte dos termos. Zero (0): confunde com procedimento chamado por CALL ou sem relação.'),
      (v_atividade, 17, 2, 'Escreva a tabela historico_exemplar, a função do trigger e o CREATE TRIGGER que grava a situação anterior, a nova, o usuário e a data e hora só quando a situação muda.', 0.2, '```sql', 'Nota cheia (0,2): tabela de histórico + função RETURNS trigger que grava OLD e NEW da situação, usuário e data e hora + CREATE TRIGGER AFTER UPDATE FOR EACH ROW com a condição de mudança. Metade (0,1): falta a condição de mudança, o usuário/data ou a tabela. Zero (0): sem a função ou sem o CREATE TRIGGER.'),
      (v_atividade, 17, 3, 'Escreva um teste que mostra o trigger funcionando, com o resultado esperado, e explique por que o histórico fica num trigger e não no código do back-end.', 0.2, '`UPDATE exemplar SET situacao = ''baixado'' WHERE id_exemplar = 2;` e depois `SELECT situacao_anterior, situacao_nova, usuario, alterado_em FROM historico_exemplar WHERE id_exemplar = 2;` → **uma linha**: disponivel → baixado, com o usuário logado e a data e hora atuais (repetir o mesmo UPDATE **não** cria nova linha; aceitar o teste pelo CALL emprestar). No trigger, o histórico é gravado **sempre**, venha a mudança do procedimento, da devolução, de outra aplicação ou de um UPDATE manual no psql; no back-end, quem altera por fora **escapa** do registro, e a regra teria de ser repetida em cada tela.', 'Nota cheia (0,2): teste com UPDATE + SELECT e o resultado esperado + justificativa (registra qualquer origem). Metade (0,1): só o teste ou só a justificativa. Zero (0): sem relação.'),
      (v_atividade, 18, 1, 'Explique os três pilares da segurança da informação com um risco de cada no caso da biblioteca.', 0.1, '**Confidencialidade** = só quem pode vê o dado (risco: vazamento do CPF dos leitores). **Integridade** = o dado está correto e completo (risco: alguém alterar a data de devolução ou zerar uma multa). **Disponibilidade** = o dado está lá quando é preciso (risco: disco queimado sem backup, balcão sem sistema).', 'Nota cheia (0,1): os três pilares com risco do caso. Metade (0,05): os três sem risco do caso, ou dois com risco. Zero (0): pilares trocados ou sem relação.'),
      (v_atividade, 18, 2, 'Classifique os dados da biblioteca nos níveis pública, interna, restrita e confidencial e diga quem acessa cada nível, do DBA ao somente leitura.', 0.2, '**Pública**: catálogo (título, autor, categoria, se há exemplar disponível) — qualquer um no site. **Interna**: quantidade de empréstimos por categoria, situação dos exemplares — funcionários. **Restrita**: nome, e-mail, telefone do leitor e seus empréstimos e multas — balcão e coordenação. **Confidencial**: CPF — só o cadastro/DBA. Hierarquia: **DBA** (postgres: tudo, backup, papéis) → **dono dos objetos** (altera estrutura) → **aplicação** (app_biblioteca: só os comandos do back-end) → **usuários por função** (balcão) → **somente leitura** (coordenação, por visões).', 'Nota cheia (0,2): os quatro níveis com dados do caso + a hierarquia de acesso. Metade (0,1): só a classificação ou só a hierarquia, ou CPF fora do confidencial. Zero (0): sem relação.'),
      (v_atividade, 18, 3, 'Diga qual pilar cada medida protege: o histórico do exemplar (R7), o backup diário testado e a permissão por coluna que esconde o CPF, e explique o cuidado com o CPF segundo a LGPD.', 0.2, 'Histórico do exemplar = **integridade** (e rastreabilidade/auditoria: quem mudou o quê e quando). Backup diário testado = **disponibilidade**. Permissão por coluna sem o CPF = **confidencialidade**. **LGPD**: o CPF é dado pessoal, coletado só com **finalidade** definida (identificar o leitor), acesso só a quem precisa (**necessidade**), protegido contra vazamento (**segurança**) e nunca usado em teste com dado real; dados de adolescentes exigem cuidado redobrado.', 'Nota cheia (0,2): as três medidas ligadas ao pilar certo + cuidado da LGPD (finalidade, necessidade ou acesso mínimo). Metade (0,1): pilares certos sem a LGPD, ou LGPD com um pilar trocado. Zero (0): sem relação.'),
      (v_atividade, 19, 1, 'Explique o princípio do menor privilégio e a diferença entre papel de grupo (NOLOGIN) e papel de login.', 0.1, '**Menor privilégio** = cada pessoa ou sistema recebe **só as permissões necessárias** para a sua função, nada além. **Papel de grupo (NOLOGIN)** junta as permissões de uma função e não entra no banco; **papel de login** é a pessoa (ou a aplicação) que entra com senha e **herda** as permissões do grupo do qual é membro.', 'Nota cheia (0,1): menor privilégio + diferença grupo × login. Metade (0,05): só uma das partes. Zero (0): sem relação.'),
      (v_atividade, 19, 2, 'Escreva os comandos que tiram o acesso de PUBLIC, criam o grupo do balcão e o login do Lucas e dão ao grupo só o necessário para R8, sem acesso ao CPF e com permissão para executar o procedimento emprestar.', 0.2, '```sql', 'Nota cheia (0,2): REVOKE de PUBLIC + grupo NOLOGIN e login no grupo + SELECT por coluna no leitor sem o CPF + EXECUTE no procedimento, sem privilégio a mais. Metade (0,1): falta o REVOKE de PUBLIC ou o EXECUTE, ou o SELECT do leitor é na tabela inteira. Zero (0): GRANT ALL, superusuário ou sem relação.'),
      (v_atividade, 19, 3, 'Escreva os comandos da coordenação (só leitura por uma visão de relatório) e um teste que prova que o balcão não vê o CPF, com o resultado esperado.', 0.2, '```sql', 'Nota cheia (0,2): coordenação só com SELECT na visão + teste do balcão com o erro de permissão no CPF. Metade (0,1): só a coordenação ou só o teste, ou coordenação com SELECT nas tabelas. Zero (0): sem relação.'),
      (v_atividade, 20, 1, 'Cite os documentos que acompanham a entrega do banco e para que serve cada um.', 0.1, '**Escopo** com a rastreabilidade R1 a R8 → objetos do banco (prova que tudo foi atendido); **DER e dicionário de dados** (estrutura, tipos e restrições para o back-end); **README** (como instalar: ordem dos scripts, script mestre, usuário da aplicação); **matriz de acesso** (quem pode o quê, R8); **registro de decisões** (o que se decidiu e por quê, ex.: inativar leitor em vez de excluir).', 'Nota cheia (0,1): pelo menos três documentos com a função de cada. Metade (0,05): documentos citados sem a função, ou só um ou dois. Zero (0): sem relação.'),
      (v_atividade, 20, 2, 'Escreva o script mestre 00-instalar.sql que roda os scripts na ordem e para no primeiro erro, e os comandos que o executam num banco de teste limpo.', 0.2, '```', 'Nota cheia (0,2): ON_ERROR_STOP + os sete scripts na ordem das dependências + banco limpo de teste + psql -f. Metade (0,1): falta o ON_ERROR_STOP ou o banco limpo, ou ordem com um script fora do lugar. Zero (0): roda no banco de produção sem teste ou ordem que quebra (segurança antes das tabelas).'),
      (v_atividade, 20, 3, 'Escreva o comando do backup de entrega, os comandos que provam que ele restaura, e explique por que essa prova é necessária.', 0.2, '`pg_dump -U postgres -d biblioteca_teste -F c -f biblioteca.dump`. Prova: `createdb -U postgres biblioteca_restaurado`, `pg_restore -U postgres -d biblioteca_restaurado biblioteca.dump` e conferir com `\dt`, `\df` e `SELECT count(*) FROM livro;` no banco restaurado (papéis são globais: aceitar `pg_dumpall --roles-only`). Backup que **nunca foi restaurado não é garantia**: o arquivo pode estar incompleto, corrompido ou sem objetos, e só a restauração prova que dá para **recuperar** o banco (disponibilidade).', 'Nota cheia (0,2): pg_dump + restauração em outro banco + conferência + motivo do teste. Metade (0,1): só o pg_dump com o motivo, ou restauração sem o motivo. Zero (0): sem comando de backup ou sem relação.');
end $$;
